function rewriteText(value) {
  if(value==='Disponibilidad')return 'Recarga'
  if(value==='Ventana útil')return 'Cuándo actuar'
  let text=value
  for(const [before,after] of orderedPhrases)text=text.replaceAll(before,after)
  return text
}
const orderedPhrases = [...plainPhrases].sort((a,b)=>b[0].length-a[0].length)
function walk(value) {
  if(typeof value==='string')return rewriteText(value)
  if(Array.isArray(value))return value.map(walk)
  if(value&&typeof value==='object')return Object.fromEntries(Object.entries(value).map(([key,value])=>[key,walk(value)]))
  return value
}

export function refreshSpanishCopy(article, heroName) {
  const a=naturalFundamentals(structuredClone(article))
  // Reviewable text fields only: never alter source identity, imported codes,
  // map coordinates, asset paths or validated ability names.
  for(const key of ['title','description','intro','sections','checklist','faq','related'])if(a[key])a[key]=walk(a[key])
  const row=heroCopy.find(([slug])=>slug===a.hero)
  const guide=guideCopy[a.slug]
  if(guide&&!a.hero)[a.title,a.description,a.intro]=guide
  if(row){
    const [,subject,description,buildSubject,buildFocus]=row
    if(a.kind==='hero'){a.title=`${heroName}: ${subject.charAt(0).toLocaleLowerCase('es')+subject.slice(1)}`;a.description=description}
    if(a.kind==='counter')a.title=`Counters de ${heroName}: héroes y objetos`
    if(a.kind==='build'){
      a.title=`Build de ${heroName}: ${buildSubject.charAt(0).toLocaleLowerCase('es')+buildSubject.slice(1)}`
      a.description=`Código ${a.buildImport.code} para importar la build de ${heroName}. ${buildFocus}`
      a.buildImport.focus=buildFocus
    }
  }
  if(a.related)a.related=a.related.map(link=>({...link,label:link.href==='/deadlock/guides/economia-almas'?'Cómo conseguir almas y cuándo comprar':link.label}))
  if(a.kind==='build')a.related=[
    {href:'/deadlock/guides/compras-objetos-activos',label:'Cómo elegir objetos y usar sus activos'},
    {href:'/deadlock/guides/dano-resistencias',label:'Qué defensa comprar según el daño recibido'},
    {href:'/deadlock/guides/economia-almas',label:'Cómo conseguir almas y cuándo comprar'},
  ]
  if(a.kind==='counter')a.related=[
    {href:'/deadlock/guides/dano-resistencias',label:'Daño, resistencias y anticuración'},
    {href:'/deadlock/guides/compras-objetos-activos',label:'Cómo elegir objetos y usar sus activos'},
    {href:'/deadlock/guides/movimiento-aguante',label:'Cómo esquivar y guardar aguante'},
  ]
  for(const section of a.sections){
    if(a.kind==='counter'&&section.title==='Objetos para responder a su plan')section.title=`Qué objetos comprar contra ${heroName}`
    section.body=section.body.map(text=>{
      if(text.startsWith('Elige la herramienta que tu equipo puede aplicar desde una posición segura. La tabla distingue'))return `Estas habilidades pueden ayudarte contra ${heroName}. Comprueba el alcance y espera a que el rival gaste su protección; tener control no garantiza que puedas aplicarlo a tiempo.`
      if(text.startsWith('Las primeras filas preparan la línea y las siguientes abren opciones'))return 'Empieza por las compras de línea. Después, elige lo que necesites para la pelea que viene; no compres todas las alternativas. Los precios son los de cada objeto completo. Si ya tienes una pieza de una mejora, en la tienda pagarás la diferencia.'
      if(text.startsWith('Después de una muerte, revisa el registro de daño y el recurso que te impidió completar tu secuencia.'))return 'Mira qué te ha matado. Si no consigues acercarte o lanzar tus habilidades, adelanta movimiento o defensa. Si llegas bien pero te falta daño, sigue con las compras ofensivas. Conserva los objetos que todavía estés aprovechando.'
      return text
    })
  }
  if(a.faq)for(const faq of a.faq)if(faq.answer.startsWith('Identifica la próxima pelea y la herramienta que te falta para participar.'))faq.answer='Si mueres antes de disparar o lanzar tus habilidades, compra primero una defensa que te permita pelear. Si ya aguantas, ahorra para mejorar el daño o recargar antes la habilidad que más uses.'
  return a
}
